grep -n '"test"' package.json; timeout 300 env NODE_OPTIONS=--experimental-vm-modules npx jest src/orchestration/orchestratorHelpers.test.ts 2>&1 | tail -20

cat >> src/orchestration/orchestratorHelpers.ts <<'EOF'

/** Adds one provider round's usage to the turn total; a round that reported nothing leaves the total as it was. */
export function addRoundUsage(
  total: UsageMetadata | undefined,
  round: UsageMetadata | undefined
): UsageMetadata | undefined {
  if (!round) return total;
  if (!total) return round;
  return {
    inputTokens: total.inputTokens + round.inputTokens,
    outputTokens: total.outputTokens + round.outputTokens,
    totalTokens: total.totalTokens + round.totalTokens,
  };
}
EOF
